const int redPin = 2;
const int greenPin = 3;
const int bluePin = 4;

void setup() {
  Serial.begin(9600);
}

void loop() {
  long redReflect = measureColor(redPin);
  long greenReflect = measureColor(greenPin);
  long blueReflect = measureColor(bluePin);

  Serial.print("R_Time: "); Serial.print(redReflect);
  Serial.print("\tG_Time: "); Serial.print(greenReflect);
  Serial.print("\tB_Time: "); Serial.println(blueReflect);

  delay(500);
}

// Function to flash an LED color and measure its discharge time
long measureColor(int pin) {
  // 1. Illuminate phase: Drive pin HIGH to light up the LED
  pinMode(pin, OUTPUT);
  digitalWrite(pin, HIGH);
  delay(10); // Short flash to illuminate the target

  // 2. Reverse bias / charge phase briefly
  // (In this setup, we pull it HIGH to store a charge)

  // 3. Sensor phase: Switch pin to INPUT and measure discharge time
  pinMode(pin, INPUT);
  digitalWrite(pin, HIGH); // Enable internal pull-up (optional, helps speed up reading)

  long startTime = micros();

  // Wait until the pin drops to LOW due to light discharge
  while (digitalRead(pin) == HIGH) {
    // Optional timeout to prevent infinite loops if it's pitch black
    if (micros() - startTime > 50000) { break; } 
  }

  long duration = micros() - startTime;
  return duration;
}
